window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-93bfb415e36112ba"]={"versions": [{"id": "FIG-93bfb415e36112ba", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Softwarekomponenten-Templates (Metamodell). Das Diagramm modelliert die Spezialisierungen der abstrakten Basisklasse <code>RTEEvent</code> sowie deren Zuordnung zu Auslösern, Kommunikationspunkten und Schnittstellenelementen im Kontext der Laufzeitumgebung (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Basisklasse ist <code>RTEEvent</code> (spezialisiert <code>Identifiable</code>). Davon abgeleitete Subklassen sind:</p>\n<ul class=\"fig-list\"><li><code>AsynchronousServerCallReturnsEvent</code>: referenziert über Assoziation <code>+eventSource 1</code> ein <code>AsynchronousServerCallPoint</code> (spezialisiert <code>ServerCallPoint</code>). Die Gegenrichtung ist <code>+event 1</code>.\n</li><li><code>DataSendCompletedEvent</code>: referenziert über Assoziation <code>+eventSource 1</code> einen <code>DataSendPoint</code> (<code>Identifiable</code>). Gegenrichtung <code>+event 0..1</code>. <code>DataSendPoint</code> referenziert über <code>«instanceRef»</code> <code>+dataElement 1</code> (Kardinalität <code>0..*</code>) ein <code>DataElementPrototype</code> (<code>DataPrototype</code>, <code>«atpPrototype»</code>).\n</li><li><code>DataReceivedEvent</code>: referenziert über <code>«instanceRef»</code> <code>+data 1</code> ein <code>DataElementPrototype</code>. Rückrelation <code>+event *</code>.\n</li><li><code>DataReceiveErrorEvent</code>: referenziert über <code>«instanceRef»</code> <code>+data 1</code> ein <code>DataElementPrototype</code>. Rückrelation <code>+event 0..1</code>.\n</li><li><code>OperationInvokedEvent</code>: referenziert über <code>«instanceRef»</code> <code>+operation 1</code> ein <code>OperationPrototype</code> (<code>Identifiable</code>, <code>«atpStructureElement»</code>). Rückrelation <code>+event 1</code>.\n</li><li><code>TimingEvent</code>: besitzt das Attribut <code>+ period: Float</code>.\n</li><li><code>ModeSwitchEvent</code>: besitzt das Attribut <code>+ activation: ModeActivationKind</code> und referenziert über <code>«instanceRef»</code> <code>+mode 1</code> (Kardinalität <code>0..*</code>) eine <code>ModeDeclaration</code> (<code>Identifiable</code>, <code>«atpStructureElement»</code>).\n</li><li><code>ModeSwitchedAckEvent</code>: referenziert über Assoziation <code>+eventSource 1</code> einen <code>ModeSwitchPoint</code> (<code>Identifiable</code>). Gegenrichtung <code>+event 0..1</code>.\n</li></ul>\n<p class=\"fig-p\">Weitere Entitäten im Modus-Kontext:</p>\n<ul class=\"fig-list\"><li><code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>«atpType»</code>): aggregiert per Komposition <code>+modeDeclaration 1..*</code> Elemente vom Typ <code>ModeDeclaration</code> und referenziert über Assoziation <code>+initialMode 1</code> eine <code>ModeDeclaration</code>.\n</li><li><code>ModeDeclarationGroupPrototype</code> (<code>Identifiable</code>, <code>«atpPrototype»</code>): typisiert über <code>«isOfType»</code> <code>+type</code> auf <code>ModeDeclarationGroup</code>.\n</li><li><code>ModeSwitchPoint</code>: referenziert über <code>«instanceRef»</code> <code>+modeGroup 1</code> (Kardinalität <code>0..*</code>) einen <code>ModeDeclarationGroupPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodellstruktur zur Abbildung von Aktivierungsmechanismen für Runnable Entities durch die RTE:</p>\n<ul class=\"fig-list\"><li>Zeitgesteuertes Triggern (<code>TimingEvent</code> mit zyklischer Periode <code>period</code>).\n</li><li>Datenempfang und Sendequittierung (<code>DataReceivedEvent</code>, <code>DataReceiveErrorEvent</code>, <code>DataSendCompletedEvent</code>).\n</li><li>Client-Server-Kommunikation (<code>OperationInvokedEvent</code> bei eingehendem Operationsaufruf, <code>AsynchronousServerCallReturnsEvent</code> bei Rückkehr eines asynchronen Aufrufs an einem <code>AsynchronousServerCallPoint</code>).\n</li><li>Modusverwaltung (<code>ModeSwitchEvent</code> bei Eintreten einer Modusaktivierungsbedingung <code>activation</code>, <code>ModeSwitchedAckEvent</code> zur Bestätigung vollzogener Modusumschaltungen an einem <code>ModeSwitchPoint</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für RTE-Event-Typen in AUTOSAR Classic. Wesentlich für die Konfiguration des RTE-Generators:</p>\n<ul class=\"fig-list\"><li>Festlegung der Auslösebedingungen (<code>eventSource</code>, Instanzreferenzen auf Datenelemente, Operationen oder Modi).\n</li><li><code>ModeActivationKind</code> steuert die Aktivierung bei Mode-Events (z. B. On-Entry, On-Exit, On-Transition).\n</li><li>Referenzen wie <code>«instanceRef»</code> erfordern konsistente Pfadauflösungen über Port- und Prototypenhierarchien in der Software-Komponentenbeschreibung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d4216d5316d57552", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Softwarekomponenten-Templates (Metamodell). Das Diagramm modelliert die Spezialisierungen der abstrakten Basisklasse <code>RTEEvent</code> sowie deren Zuordnung zu Auslösern, Kommunikationspunkten und Schnittstellenelementen im Kontext der Laufzeitumgebung (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Basisklasse ist <code>RTEEvent</code> (spezialisiert <code>Identifiable</code>). Davon abgeleitete Subklassen sind:</p>\n<ul class=\"fig-list\"><li><code>AsynchronousServerCallReturnsEvent</code>: referenziert über Assoziation <code>+eventSource 1</code> ein <code>AsynchronousServerCallPoint</code> (spezialisiert <code>ServerCallPoint</code>). Die Gegenrichtung ist <code>+event 1</code>.\n</li><li><code>DataSendCompletedEvent</code>: referenziert über Assoziation <code>+eventSource 1</code> einen <code>DataSendPoint</code> (<code>Identifiable</code>). Gegenrichtung <code>+event 0..1</code>. <code>DataSendPoint</code> referenziert über <code>«instanceRef»</code> <code>+dataElement 1</code> (Kardinalität <code>0..*</code>) ein <code>DataElementPrototype</code> (<code>DataPrototype</code>, <code>«atpPrototype»</code>).\n</li><li><code>DataReceivedEvent</code>: referenziert über <code>«instanceRef»</code> <code>+data 1</code> ein <code>DataElementPrototype</code>. Rückrelation <code>+event *</code>.\n</li><li><code>DataReceiveErrorEvent</code>: referenziert über <code>«instanceRef»</code> <code>+data 1</code> ein <code>DataElementPrototype</code>. Rückrelation <code>+event 0..1</code>.\n</li><li><code>OperationInvokedEvent</code>: referenziert über <code>«instanceRef»</code> <code>+operation 1</code> ein <code>OperationPrototype</code> (<code>Identifiable</code>, <code>«atpStructureElement»</code>). Rückrelation <code>+event 1</code>.\n</li><li><code>TimingEvent</code>: besitzt das Attribut <code>+ period: Float</code>.\n</li><li><code>ModeSwitchEvent</code>: besitzt das Attribut <code>+ activation: ModeActivationKind</code> und referenziert über <code>«instanceRef»</code> <code>+mode 1</code> (Kardinalität <code>0..*</code>) eine <code>ModeDeclaration</code> (<code>Identifiable</code>, <code>«atpStructureElement»</code>).\n</li><li><code>ModeSwitchedAckEvent</code>: referenziert über Assoziation <code>+eventSource 1</code> einen <code>ModeSwitchPoint</code> (<code>Identifiable</code>). Gegenrichtung <code>+event 0..1</code>.\n</li></ul>\n<p class=\"fig-p\">Weitere Entitäten im Modus-Kontext:</p>\n<ul class=\"fig-list\"><li><code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>«atpType»</code>): aggregiert per Komposition <code>+modeDeclaration 1..*</code> Elemente vom Typ <code>ModeDeclaration</code> und referenziert über Assoziation <code>+initialMode 1</code> eine <code>ModeDeclaration</code>.\n</li><li><code>ModeDeclarationGroupPrototype</code> (<code>Identifiable</code>, <code>«atpPrototype»</code>): typisiert über <code>«isOfType»</code> <code>+type</code> auf <code>ModeDeclarationGroup</code>.\n</li><li><code>ModeSwitchPoint</code>: referenziert über <code>«instanceRef»</code> <code>+modeGroup 1</code> (Kardinalität <code>0..*</code>) einen <code>ModeDeclarationGroupPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodellstruktur zur Abbildung von Aktivierungsmechanismen für Runnable Entities durch die RTE:</p>\n<ul class=\"fig-list\"><li>Zeitgesteuertes Triggern (<code>TimingEvent</code> mit zyklischer Periode <code>period</code>).\n</li><li>Datenempfang und Sendequittierung (<code>DataReceivedEvent</code>, <code>DataReceiveErrorEvent</code>, <code>DataSendCompletedEvent</code>).\n</li><li>Client-Server-Kommunikation (<code>OperationInvokedEvent</code> bei eingehendem Operationsaufruf, <code>AsynchronousServerCallReturnsEvent</code> bei Rückkehr eines asynchronen Aufrufs an einem <code>AsynchronousServerCallPoint</code>).\n</li><li>Modusverwaltung (<code>ModeSwitchEvent</code> bei Eintreten einer Modusaktivierungsbedingung <code>activation</code>, <code>ModeSwitchedAckEvent</code> zur Bestätigung vollzogener Modusumschaltungen an einem <code>ModeSwitchPoint</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für RTE-Event-Typen in AUTOSAR Classic. Wesentlich für die Konfiguration des RTE-Generators:</p>\n<ul class=\"fig-list\"><li>Festlegung der Auslösebedingungen (<code>eventSource</code>, Instanzreferenzen auf Datenelemente, Operationen oder Modi).\n</li><li><code>ModeActivationKind</code> steuert die Aktivierung bei Mode-Events (z. B. On-Entry, On-Exit, On-Transition).\n</li><li>Referenzen wie <code>«instanceRef»</code> erfordern konsistente Pfadauflösungen über Port- und Prototypenhierarchien in der Software-Komponentenbeschreibung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-93bfb415e36112ba", "to": "FIG-d4216d5316d57552", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
